package com.novalang.bukkit.types.inventory;
import com.novalang.bukkit.Requires; import com.novalang.bukkit.types.value.NovaTypeSupport; import com.novalang.runtime.host.JavaTypes; import org.bukkit.inventory.meta.Repairable;
@Requires(classes = {"org.bukkit.inventory.meta.Repairable"}) public final class NovaRepairable { private NovaRepairable() { } public static void register(JavaTypes.Builder b) { b.extension(Repairable.class,"hasRepairCost",f->f.returns(Boolean.class).invoke(a->NovaTypeSupport.argument(a,0,Repairable.class).hasRepairCost())); b.extension(Repairable.class,"repairCost",f->f.returns(Integer.class).invoke(a->NovaTypeSupport.argument(a,0,Repairable.class).getRepairCost())); b.extension(Repairable.class,"setRepairCost",f->f.param("cost",Integer.class).returns(Void.TYPE).invoke(a->{NovaTypeSupport.argument(a,0,Repairable.class).setRepairCost(NovaTypeSupport.argument(a,1,Integer.class));return null;})); } }
